import React, { useEffect, useState } from "react";

function App() {
	  const [users, setUsers] = useState([]);
	  const [name, setName] = useState("");
	  const [email, setEmail] = useState("");

	  const API_URL = "http://127.0.0.1:5555/users";

	  const fetchUsers = () => {
		      fetch(API_URL)
		        .then((res) => res.json())
		        .then((data) => setUsers(data))
		        .catch((err) => console.error(err));
		    };

	  useEffect(() => {
		      fetchUsers();
		    }, []);

	  const addUser = async () => {
		      if (!name || !email) {
			            alert("Enter Name and Email");
			            return;
			          }

		      await fetch(API_URL, {
			            method: "POST",
			            headers: {
					            "Content-Type": "application/json",
					          },
			            body: JSON.stringify({
					            name,
					            email,
					          }),
			          });

		      setName("");
		      setEmail("");

		      fetchUsers();
		    };

	  const deleteUser = async (id) => {
		      await fetch(`${API_URL}/${id}`, {
			            method: "DELETE",
			          });

		      fetchUsers();
		    };

	  return (
		      <div
		        style={{
				        maxWidth: "900px",
					        margin: "40px auto",
					        fontFamily: "Arial",
					      }}
		      >
		        <h1 style={{ textAlign: "center" }}>
		          Employee Management System
		        </h1>

		        <div
		          style={{
				            padding: "20px",
					            border: "1px solid #ddd",
					            borderRadius: "10px",
					            marginBottom: "30px",
					          }}
		        >
		          <h3>Add Employee</h3>

		          <input
		            type="text"
		            placeholder="Employee Name"
		            value={name}
		            onChange={(e) => setName(e.target.value)}
		            style={{
				                padding: "10px",
					                width: "250px",
					                marginRight: "10px",
					              }}
		          />

		          <input
		            type="email"
		            placeholder="Employee Email"
		            value={email}
		            onChange={(e) => setEmail(e.target.value)}
		            style={{
				                padding: "10px",
					                width: "250px",
					                marginRight: "10px",
					              }}
		          />

		          <button
		            onClick={addUser}
		            style={{
				                padding: "10px 20px",
					                backgroundColor: "green",
					                color: "white",
					                border: "none",
					                cursor: "pointer",
					              }}
		          >
		            Add Employee
		          </button>
		        </div>

		        <table
		          style={{
				            width: "100%",
					            borderCollapse: "collapse",
					          }}
		        >
		          <thead>
		            <tr style={{ backgroundColor: "#f2f2f2" }}>
		              <th style={{ border: "1px solid #ddd", padding: "10px" }}>
		                ID
		              </th>
		              <th style={{ border: "1px solid #ddd", padding: "10px" }}>
		                Name
		              </th>
		              <th style={{ border: "1px solid #ddd", padding: "10px" }}>
		                Email
		              </th>
		              <th style={{ border: "1px solid #ddd", padding: "10px" }}>
		                Action
		              </th>
		            </tr>
		          </thead>

		          <tbody>
		            {users.map((user) => (
				                <tr key={user.id}>
				                  <td style={{ border: "1px solid #ddd", padding: "10px" }}>
				                    {user.id}
				                  </td>

				                  <td style={{ border: "1px solid #ddd", padding: "10px" }}>
				                    {user.name}
				                  </td>

				                  <td style={{ border: "1px solid #ddd", padding: "10px" }}>
				                    {user.email}
				                  </td>

				                  <td style={{ border: "1px solid #ddd", padding: "10px" }}>
				                    <button
				                      onClick={() => deleteUser(user.id)}
				                      style={{
							                          backgroundColor: "red",
								                          color: "white",
								                          border: "none",
								                          padding: "8px 14px",
								                          cursor: "pointer",
								                        }}
				                    >
				                      Delete
				                    </button>
				                  </td>
				                </tr>
				              ))}
		          </tbody>
		        </table>
		      </div>
		    );
}

export default App;
